const d = msg.payload;
const out = new Array(11).fill(null);
const ult = context.get('ult') || {};
// envia só quando muda (evita brigar com o usuário mexendo no controle)
function seMudou(i, chave, valor) {
    if (ult[chave] !== valor) { ult[chave] = valor; out[i] = { payload: valor }; }
}

if (!d || d.online === false) {
    out[9] = { payload: '🔴 OFFLINE (serviço parado)' };
    node.status({ fill: 'red', shape: 'ring', text: 'offline' });
    context.set('ult', ult);
    return out;
}
const fmt = (v, u) => (v === null || v === undefined) ? '—' : v.toFixed(1) + u;

if (d.solo_pct !== null) out[0] = { payload: d.solo_pct };
if (d.temp !== null) out[1] = { payload: d.temp };
if (d.umid_ar !== null) out[2] = { payload: d.umid_ar };

const pontos = [];
if (d.solo_pct !== null) pontos.push({ topic: 'Solo (%)', payload: d.solo_pct });
if (d.umid_ar !== null) pontos.push({ topic: 'Umid. ar (%)', payload: d.umid_ar });
if (d.temp !== null) pontos.push({ topic: 'Temp. (°C)', payload: d.temp });
pontos.push({ topic: 'Bomba (on=100)', payload: d.bomba ? 100 : 0 });
out[3] = pontos;

out[4] = { payload: d.tem_agua ? '💧 Com água' : '⚠️ VAZIO' };
out[5] = { payload: d.bomba ? `🟢 LIGADA (${d.bomba_seg} s)` : '⚪ Desligada' };
out[6] = { payload: d.motivo };

const c = d.cfg || {};
seMudou(7, 'modo', c.modo);
const ajuda = `${c.limiar}|${c.tempo_rega}|${c.tempo_espera}|${c.tempo_max_manual}`;
if (ult.ajuda !== ajuda) {
    ult.ajuda = ajuda;
    out[10] = { payload: { limiar: c.limiar, tempo_rega: c.tempo_rega, tempo_espera: c.tempo_espera,
                           tempo_max_manual: c.tempo_max_manual } };
}

const e = d.erros || {};
out[8] = { payload: [
    ['Tensão do solo (A0)', d.solo_v === null ? '—' : d.solo_v.toFixed(3) + ' V'],
    ['Calibração', `seco ${c.solo_seco_v} V · molhado ${c.solo_molhado_v} V`],
    ['Contato da boia', d.boia_fechada ? 'fechado' : 'aberto'],
    ['Temp / umid. ar', `${fmt(d.temp, ' °C')} / ${fmt(d.umid_ar, ' %')}`],
    ['ADS1115', e.ads ? 'ERRO: ' + e.ads : 'ok', !!e.ads],
    ['DHT22', e.dht ? 'ERRO: ' + e.dht
        : `ok · última leitura há ${d.dht_idade ?? '—'} s · ${d.dht_taxa}% das tentativas`, !!e.dht],
    ['Atualizado', new Date(d.ts).toLocaleTimeString('pt-BR')],
]};
out[9] = { payload: '🟢 online' };
node.status({ fill: d.bomba ? 'green' : 'grey', shape: 'dot',
              text: `solo ${fmt(d.solo_pct, '%')} · bomba ${d.bomba ? 'ON' : 'off'}` });
context.set('ult', ult);
return out;

// Estado local (irrigacao/estado, a cada ~2 s) -> pontos para o Ubidots.
// O Ubidots só guarda números: booleanos viram 0/1.
const d = msg.payload;
if (!d || d.online === false) {
    node.status({ fill: 'red', shape: 'ring', text: 'serviço offline' });
    return null;
}
const agora = Date.now();
const est = {
    modo_auto: (d.cfg && d.cfg.modo === 'auto') ? 1 : 0,
    bomba: d.bomba ? 1 : 0,
    agua: d.tem_agua ? 1 : 0,
};
const ant = flow.get('ub_estado');
flow.set('ub_estado', est);

const dots = {};
// eventos: na hora em que mudam (e todos na primeira mensagem, para sobrescrever
// valores antigos que tenham ficado no Ubidots)
for (const k of Object.keys(est)) {
    if (!ant || ant[k] !== est[k]) dots[k] = est[k];
}
// depois de um comando vindo do Ubidots, reenvia o estado real dos controles
// (ex.: rega recusada por falta de água -> o botão volta para 0)
const rs = flow.get('ub_resync') || 0;
if (rs && agora >= rs) {
    flow.set('ub_resync', 0);
    dots.modo_auto = est.modo_auto;
    dots.bomba = est.bomba;
}
// sensores: a cada 120 segundos
if (agora - (context.get('ult_sens') || 0) >= 120 * 1000) {
    context.set('ult_sens', agora);
    if (d.solo_pct !== null) dots.solo = d.solo_pct;
    if (d.temp !== null) dots.temperatura = d.temp;
    if (d.umid_ar !== null) dots.umidade_ar = d.umid_ar;
}
if ('bomba' in dots && d.motivo) {
    dots.bomba = { value: dots.bomba, context: { motivo: String(d.motivo).slice(0, 100) } };
}
if (!Object.keys(dots).length) return null;
node.status({ fill: 'green', shape: 'dot',
              text: new Date(agora).toLocaleTimeString('pt-BR') + ' · ' + Object.keys(dots).join(', ') });
msg.payload = dots;
return msg;

// Valor de um widget do Ubidots (/lv = só o número, ex. "1.0") -> irrigacao/cmd.
// Ignora ecos: só age se o valor for diferente do estado real da Pi.
if (Date.now() - (flow.get('ub_inicio') || 0) < 10000) {
    // logo após conectar o Ubidots devolve o último valor guardado; não é comando novo
    return null;
}
const est = flow.get('ub_estado');
if (!est) return null;
const v = parseFloat(String(msg.payload)) >= 0.5 ? 1 : 0;
const variavel = msg.topic.split('/')[4];   // /v1.6/devices/<device>/<variavel>/lv
let cmd = null;
if (variavel === 'modo_auto' && v !== est.modo_auto) {
    cmd = { modo: v ? 'auto' : 'manual' };
} else if (variavel === 'bomba' && v !== est.bomba) {
    // ligar: no automático vira uma dose de rega; no manual, liga até tempo_max_manual.
    // As travas (boia, tempo máximo) continuam no irrigacao.py.
    cmd = v ? (est.modo_auto ? { regar: true } : { bomba: true }) : { bomba: false };
}
if (!cmd) return null;
flow.set('ub_resync', Date.now() + 5000);
node.status({ fill: 'blue', shape: 'dot',
              text: new Date().toLocaleTimeString('pt-BR') + ' ' + JSON.stringify(cmd) });
return { payload: cmd };
